mapper.select:
SELECT
    admin_audit_log_id, admin_user_id, action_type, target_type, target_id,
    before_data::text AS before_data, after_data::text AS after_data,
    request_id, host(ip_address) AS ip_address, user_agent, occurred_at
FROM admin_audit_logs


        AND target_type = #{targetType}


        AND target_id = #{targetId}


ORDER BY occurred_at DESC, admin_audit_log_id DESC
LIMIT #{limit}
